-- ============================================================================ -- LOGIX FASHION - Esquema de Base de Datos para Supabase (PostgreSQL) -- ============================================================================ -- INSTRUCCIONES: -- 1. Entra a tu proyecto en Supabase (https://supabase.com) -- 2. Ve al SQL Editor en el menÃº lateral izquierdo -- 3. Copia y pega TODO este cÃ³digo y haz clic en "Run" -- ============================================================================  -- â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â• -- PASO 0: ARREGLAR PERMISOS DEL ESQUEMA PUBLIC (soluciona error 42501) -- â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â• GRANT ALL ON SCHEMA public TO postgres; GRANT ALL ON SCHEMA public TO public; ALTER SCHEMA public OWNER TO postgres;  -- ------------------------------------------------------------ -- 1. TABLA: admins (usuarios del panel administrativo) -- ------------------------------------------------------------ CREATE TABLE IF NOT EXISTS admins (   id UUID PRIMARY KEY DEFAULT gen_random_uuid(),   email TEXT UNIQUE NOT NULL,   password_hash TEXT NOT NULL,   is_active BOOLEAN NOT NULL DEFAULT true,   created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),   updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW() );  -- ------------------------------------------------------------ -- 2. TABLA: inventario_productos (catÃ¡logo de modelos) -- ------------------------------------------------------------ CREATE TABLE IF NOT EXISTS inventario_productos (   id UUID PRIMARY KEY DEFAULT gen_random_uuid(),   model_id TEXT UNIQUE NOT NULL,   name TEXT NOT NULL,   category TEXT NOT NULL,   price DECIMAL(10,2) NOT NULL DEFAULT 0,   created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),   updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW() );  -- ------------------------------------------------------------ -- 3. TABLA: inventario_stock (stock por color y talla) -- ------------------------------------------------------------ CREATE TABLE IF NOT EXISTS inventario_stock (   id UUID PRIMARY KEY DEFAULT gen_random_uuid(),   product_id UUID NOT NULL REFERENCES inventario_productos(id) ON DELETE CASCADE,   color_name TEXT NOT NULL,   color_hex TEXT NOT NULL DEFAULT '#000000',   size TEXT NOT NULL CHECK (size IN ('S', 'M', 'L', 'XL')),   quantity INTEGER NOT NULL DEFAULT 0 CHECK (quantity >= 0),   UNIQUE(product_id, color_name, size),   created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),   updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW() );  -- ------------------------------------------------------------ -- 4. TABLA: pedidos (Ã³rdenes de clientes) -- ------------------------------------------------------------ CREATE TABLE IF NOT EXISTS pedidos (   id UUID PRIMARY KEY DEFAULT gen_random_uuid(),   order_id TEXT UNIQUE NOT NULL,   customer_name TEXT NOT NULL,   customer_phone TEXT NOT NULL,   customer_dni TEXT,   customer_district TEXT NOT NULL,   customer_address TEXT NOT NULL,   customer_ref TEXT,   destination_type TEXT NOT NULL CHECK (destination_type IN ('Lima', 'Provincia')),   province_data JSONB NOT NULL DEFAULT '{}'::jsonb,   items JSONB NOT NULL DEFAULT '[]'::jsonb,   shipping_cost DECIMAL(10,2) NOT NULL DEFAULT 0,   total DECIMAL(10,2) NOT NULL DEFAULT 0,   status TEXT NOT NULL DEFAULT 'Pagado / No enviado',   created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),   updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW() );  -- ------------------------------------------------------------ -- 5. ÃNDICES para optimizar consultas -- ------------------------------------------------------------ CREATE INDEX IF NOT EXISTS idx_pedidos_order_id ON pedidos(order_id); CREATE INDEX IF NOT EXISTS idx_pedidos_created_at ON pedidos(created_at DESC); CREATE INDEX IF NOT EXISTS idx_pedidos_status ON pedidos(status); CREATE INDEX IF NOT EXISTS idx_pedidos_phone ON pedidos(customer_phone); CREATE INDEX IF NOT EXISTS idx_stock_product_id ON inventario_stock(product_id); CREATE INDEX IF NOT EXISTS idx_stock_lookup ON inventario_stock(product_id, color_name, size);  -- ------------------------------------------------------------ -- 6. FUNCIÃ“N: descuento atÃ³mico de stock (evita sobreventa) -- ------------------------------------------------------------ -- Esta funciÃ³n se ejecuta con privilegios del propietario (SECURITY DEFINER) -- para que el pÃºblico (anon) pueda descontar stock sin necesidad de ser admin. CREATE OR REPLACE FUNCTION fn_reserve_stock(   p_product_id UUID,   p_color_name TEXT,   p_size TEXT,   p_qty INTEGER ) RETURNS BOOLEAN AS $$ DECLARE   v_current_quantity INTEGER; BEGIN   -- Verificar stock disponible de forma atÃ³mica   SELECT quantity INTO v_current_quantity   FROM inventario_stock   WHERE product_id = p_product_id     AND color_name = p_color_name     AND size = p_size   FOR UPDATE;  -- Bloqueo de fila hasta que termine la transacciÃ³n    IF v_current_quantity IS NULL THEN     RETURN FALSE;  -- El producto/color/talla no existe   END IF;    IF v_current_quantity < p_qty THEN     RETURN FALSE;  -- Stock insuficiente   END IF;    -- Descontar stock (nunca negativo gracias al CHECK quantity >= 0)   UPDATE inventario_stock   SET quantity = quantity - p_qty,       updated_at = NOW()   WHERE product_id = p_product_id     AND color_name = p_color_name     AND size = p_size     AND quantity >= p_qty;    RETURN TRUE; END; $$ LANGUAGE plpgsql SECURITY DEFINER;  -- ------------------------------------------------------------ -- 7. POLÃTICAS DE SEGURIDAD (RLS - Row Level Security) -- ------------------------------------------------------------  -- Habilitar RLS en todas las tablas ALTER TABLE admins ENABLE ROW LEVEL SECURITY; ALTER TABLE inventario_productos ENABLE ROW LEVEL SECURITY; ALTER TABLE inventario_stock ENABLE ROW LEVEL SECURITY; ALTER TABLE pedidos ENABLE ROW LEVEL SECURITY;  -- ------------------------------------------------------------ -- 7a. POLÃTICA: admins (solo admin autenticado puede leer/escribir) -- ------------------------------------------------------------ DROP POLICY IF EXISTS "Admins can read own data" ON admins; CREATE POLICY "Admins can read own data" ON admins   FOR SELECT USING (auth.uid() IS NOT NULL);  DROP POLICY IF EXISTS "Admins can insert" ON admins; CREATE POLICY "Admins can insert" ON admins   FOR INSERT WITH CHECK (auth.uid() IS NOT NULL);  DROP POLICY IF EXISTS "Admins can update" ON admins; CREATE POLICY "Admins can update" ON admins   FOR UPDATE USING (auth.uid() IS NOT NULL);  -- ------------------------------------------------------------ -- 7b. POLÃTICAS: inventario_productos -- ------------------------------------------------------------ -- El pÃºblico puede VER los productos (para el catÃ¡logo del cliente) DROP POLICY IF EXISTS "Public can view products" ON inventario_productos; CREATE POLICY "Public can view products" ON inventario_productos   FOR SELECT USING (true);  -- Solo admin autenticado puede crear/editar/eliminar productos DROP POLICY IF EXISTS "Authenticated can manage products" ON inventario_productos; CREATE POLICY "Authenticated can manage products" ON inventario_productos   FOR ALL USING (auth.uid() IS NOT NULL);  -- ------------------------------------------------------------ -- 7c. POLÃTICAS: inventario_stock -- ------------------------------------------------------------ -- El pºblico puede VER el stock (para saber quØ hay disponible) DROP POLICY IF EXISTS "Public can view stock" ON inventario_stock; CREATE POLICY "Public can view stock" ON inventario_stock   FOR SELECT USING (true);  -- Solo admin autenticado puede gestionar stock DROP POLICY IF EXISTS "Authenticated can manage stock" ON inventario_stock; CREATE POLICY "Authenticated can manage stock" ON inventario_stock   FOR ALL USING (auth.uid() IS NOT NULL);  -- ------------------------------------------------------------ -- 7d. POLÃTICAS: pedidos -- ------------------------------------------------------------ -- El pÃºblico puede INSERTAR pedidos (cliente realiza un pedido) DROP POLICY IF EXISTS "Public can insert orders" ON pedidos; CREATE POLICY "Public can insert orders" ON pedidos   FOR INSERT WITH CHECK (true);  -- El pÃºblico NO puede leer pedidos (evita que vea Ã³rdenes de otros clientes)  -- Solo admin autenticado puede leer y actualizar pedidos DROP POLICY IF EXISTS "Authenticated can read orders" ON pedidos; CREATE POLICY "Authenticated can read orders" ON pedidos   FOR SELECT USING (auth.uid() IS NOT NULL);  DROP POLICY IF EXISTS "Authenticated can update orders" ON pedidos; CREATE POLICY "Authenticated can update orders" ON pedidos   FOR UPDATE USING (auth.uid() IS NOT NULL);  -- ------------------------------------------------------------ -- 8. DATOS INICIALES: Productos de ejemplo (LOGIX FASHION) -- ------------------------------------------------------------ -- Ejecuta esta secciÃ³n una sola vez para poblar el catÃ¡logo inicial.  INSERT INTO inventario_productos (model_id, name, category, price) VALUES   ('MOD-001', 'Polo Oversize Streetwear 24/1', 'Polos', 55.00),   ('MOD-002', 'Hoodie Heavy Cotton 400g Felpado', 'Polerones', 95.00),   ('MOD-003', 'Casaca Bomber Impermeable', 'Casacas', 139.00),   ('MOD-004', 'PantalÃ³n Cargo Relaxed Fit 6 Bolsillos', 'Pantalones', 85.00),   ('MOD-005', 'Crop Top Ribbed AlgodÃ³n Pima', 'Tops', 38.00) ON CONFLICT (model_id) DO NOTHING;  -- Stock MOD-001 (Polo Oversize) - Negro Washed INSERT INTO inventario_stock (product_id, color_name, color_hex, size, quantity) SELECT id, 'Negro Washed', '#1f2421', 'S', 12 FROM inventario_productos WHERE model_id = 'MOD-001' ON CONFLICT (product_id, color_name, size) DO NOTHING; INSERT INTO inventario_stock (product_id, color_name, color_hex, size, quantity) 